$ {
      position: relative;
      width: 124px;
      height: 56px;
      border-radius: 999px;
      background: radial-gradient(circle at 50% 50%, #101622 0%, #070a10 100%);
      box-shadow:
        inset 0 4px 12px rgba(0, 0, 0, 0.9),
        inset 0 -1px 2px rgba(255, 255, 255, 0.08),
        0 0 0 1px rgba(255, 255, 255, 0.08);
      transition: box-shadow 0.5s ease;
    }
.ferro-goo-layer {
      position: absolute;
      inset: 0;
      filter: url('#ferro-goo');
      pointer-events: none;
    }
.ferro-anchor-l,
    .ferro-anchor-r {
      position: absolute;
      top: 50%;
      width: 14px;
      height: 14px;
      border-radius: 50%;
      transform: translateY(-50%);
      transition: background 0.45s ease, transform 0.45s ease;
    }
.ferro-anchor-l {
      left: 20px;
      background: #94a3b8;
    }
.ferro-anchor-r {
      right: 20px;
      background: #06b6d4;
      transform: translateY(-50%) scale(0.7);
    }
.ferro-main-blob {
      position: absolute;
      top: 7px;
      left: 7px;
      width: 42px;
      height: 42px;
      border-radius: 50%;
      background: radial-gradient(circle at 32% 28%, #f8fafc 0%, #94a3b8 42%, #334155 88%, #0f172a 100%);
      transition:
        transform 0.65s cubic-bezier(0.68, -0.45, 0.26, 1.4),
        background 0.45s ease;
    }
.ferro-satellite {
      position: absolute;
      top: 22px;
      left: 22px;
      width: 12px;
      height: 12px;
      border-radius: 50%;
      background: #cbd5e1;
      opacity: 0.9;
      transition:
        transform 0.72s cubic-bezier(0.34, 1.65, 0.64, 1),
        background 0.45s ease;
    }
.ferro-micro-1 {
      position: absolute;
      top: 14px;
      left: 26px;
      width: 7px;
      height: 7px;
      border-radius: 50%;
      background: #94a3b8;
      transition: transform 0.8s cubic-bezier(0.22, 1.4, 0.36, 1), background 0.45s ease;
    }
.ferro-specular {
      position: absolute;
      top: 13px;
      left: 16px;
      width: 12px;
      height: 6px;
      border-radius: 999px;
      background: rgba(255, 255, 255, 0.75);
      transform: rotate(-28deg);
      filter: blur(0.4px);
      pointer-events: none;
      transition: transform 0.65s cubic-bezier(0.68, -0.45, 0.26, 1.4);
    }
$on {
      box-shadow:
        inset 0 4px 12px rgba(0, 0, 0, 0.9),
        0 0 24px rgba(6, 182, 212, 0.35),
        0 0 0 1px rgba(34, 211, 238, 0.45);
    }
$on .ferro-main-blob {
      transform: translateX(68px);
      background: radial-gradient(circle at 32% 28%, #ecfeff 0%, #22d3ee 40%, #059669 85%, #064e3b 100%);
      animation: KF_ferroSnapRight 0.68s ease;
    }
$off .ferro-main-blob {
      animation: KF_ferroSnapLeft 0.68s ease;
    }
$on .ferro-satellite {
      transform: translateX(52px) translateY(-11px) scale(0.85);
      background: #34d399;
    }
$on .ferro-micro-1 {
      transform: translateX(76px) translateY(18px) scale(1.1);
      background: #22d3ee;
    }
$on .ferro-anchor-r {
      transform: translateY(-50%) scale(1.15);
    }
$on .ferro-specular {
      transform: translateX(68px) rotate(-28deg);
    }
@keyframes KF_ferroSnapRight {
      0% { width: 42px; border-radius: 50%; }
      35% { width: 72px; border-radius: 24px; }
      65% { width: 36px; border-radius: 50%; }
      100% { width: 42px; border-radius: 50%; }
    }
@keyframes KF_ferroSnapLeft {
      0% { width: 42px; border-radius: 50%; }
      35% { width: 72px; border-radius: 24px; margin-left: -30px; }
      65% { width: 36px; border-radius: 50%; margin-left: 4px; }
      100% { width: 42px; border-radius: 50%; margin-left: 0; }
    }

$ {
      position: relative;
      width: 126px;
      height: 56px;
      border-radius: 999px;
      background: #070b14;
      border: 1.5px solid #1e293b;
      box-shadow: inset 0 3px 12px rgba(0, 0, 0, 0.95);
      overflow: hidden;
      transition: border-color 0.4s ease, box-shadow 0.4s ease;
    }
.plasma-capacitor-bars {
      position: absolute;
      inset: 0;
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 4px;
      padding: 0 26px;
      z-index: 1;
    }
.plasma-capacitor-bars span {
      width: 3px;
      height: 14px;
      border-radius: 2px;
      background: #1e293b;
      transition: background 0.3s ease, box-shadow 0.3s ease, height 0.3s ease;
    }
$on .plasma-capacitor-bars span:nth-child(1) { transition-delay: 0.05s; background: #38bdf8; box-shadow: 0 0 8px #38bdf8; height: 18px; }
$on .plasma-capacitor-bars span:nth-child(2) { transition-delay: 0.10s; background: #38bdf8; box-shadow: 0 0 8px #38bdf8; height: 22px; }
$on .plasma-capacitor-bars span:nth-child(3) { transition-delay: 0.15s; background: #818cf8; box-shadow: 0 0 10px #818cf8; height: 26px; }
$on .plasma-capacitor-bars span:nth-child(4) { transition-delay: 0.20s; background: #38bdf8; box-shadow: 0 0 8px #38bdf8; height: 22px; }
$on .plasma-capacitor-bars span:nth-child(5) { transition-delay: 0.25s; background: #38bdf8; box-shadow: 0 0 8px #38bdf8; height: 18px; }
.plasma-arc-svg {
      position: absolute;
      inset: 0;
      width: 100%;
      height: 100%;
      z-index: 2;
      pointer-events: none;
      opacity: 0;
      transition: opacity 0.25s ease;
    }
$on .plasma-arc-svg {
      opacity: 1;
    }
.plasma-core {
      position: absolute;
      top: 5px;
      left: 5px;
      width: 44px;
      height: 44px;
      border-radius: 50%;
      background: radial-gradient(circle, #1e293b 0%, #090d16 100%);
      border: 1.5px solid #334155;
      display: flex;
      align-items: center;
      justify-content: center;
      z-index: 3;
      transition: transform 0.52s cubic-bezier(0.34, 1.45, 0.64, 1), border-color 0.4s ease, box-shadow 0.4s ease;
    }
.plasma-turbine {
      position: absolute;
      inset: 3px;
      width: 36px;
      height: 36px;
      transition: transform 0.5s ease;
    }
.plasma-nucleus {
      width: 14px;
      height: 14px;
      border-radius: 50%;
      background: #1e293b;
      border: 2px solid #475569;
      transition: all 0.35s ease;
    }
$on {
      border-color: #38bdf8;
      box-shadow:
        inset 0 2px 14px rgba(56, 189, 248, 0.35),
        0 0 25px rgba(56, 189, 248, 0.4);
    }
$on .plasma-core {
      transform: translateX(70px);
      border-color: #7dd3fc;
      box-shadow: 0 0 18px rgba(56, 189, 248, 0.75);
    }
$on .plasma-turbine {
      animation: KF_turbineSpin 1.6s linear infinite;
    }
$on .plasma-nucleus {
      background: #ffffff;
      border-color: #38bdf8;
      box-shadow: 0 0 12px #fff, 0 0 22px #38bdf8, 0 0 34px #6366f1;
    }
@keyframes KF_turbineSpin {
      from { transform: rotate(0deg); }
      to { transform: rotate(360deg); }
    }

$ {
      position: relative;
      width: 126px;
      height: 56px;
      border-radius: 999px;
      background: linear-gradient(180deg, #070b19 0%, #17203d 65%, #1e293b 100%);
      box-shadow:
        inset 0 4px 12px rgba(0, 0, 0, 0.8),
        0 0 0 1px rgba(255, 255, 255, 0.12);
      overflow: hidden;
      transition: background 0.7s cubic-bezier(0.4, 0, 0.2, 1), box-shadow 0.6s ease;
    }
.biome-stars span {
      position: absolute;
      background: #fff;
      border-radius: 50%;
      box-shadow: 0 0 6px #fff;
      transition: transform 0.6s ease, opacity 0.45s ease;
    }
.biome-stars span:nth-child(1) { width: 2.5px; height: 2.5px; top: 11px; right: 26px; animation: KF_starPulse 1.9s infinite alternate; }
.biome-stars span:nth-child(2) { width: 2px; height: 2px; top: 22px; right: 44px; animation: KF_starPulse 2.4s infinite alternate 0.4s; }
.biome-stars span:nth-child(3) { width: 3px; height: 3px; top: 14px; right: 58px; animation: KF_starPulse 1.7s infinite alternate 0.8s; }
.biome-stars span:nth-child(4) { width: 2px; height: 2px; top: 32px; right: 32px; background: #a3e635; box-shadow: 0 0 6px #a3e635; animation: KF_starPulse 1.4s infinite alternate; }
@keyframes KF_starPulse {
      0% { opacity: 0.3; transform: scale(0.8); }
      100% { opacity: 1; transform: scale(1.25); }
    }
.biome-hills {
      position: absolute;
      bottom: -8px;
      left: -6px;
      right: -6px;
      height: 22px;
      background: #0f172a;
      border-radius: 50% 50% 0 0 / 100% 100% 0 0;
      transition: background 0.7s ease;
      z-index: 2;
    }
.biome-hills::after {
      content: '';
      position: absolute;
      right: 4px;
      bottom: 2px;
      width: 68px;
      height: 18px;
      background: #1e293b;
      border-radius: 50% 50% 0 0 / 100% 100% 0 0;
      transition: background 0.7s ease;
    }
.biome-celestial {
      position: absolute;
      top: 7px;
      left: 8px;
      width: 40px;
      height: 40px;
      border-radius: 50%;
      background: #f1f5f9;
      box-shadow: 0 0 16px rgba(241, 245, 249, 0.75), inset -6px -4px 0 #cbd5e1;
      z-index: 3;
      transition:
        transform 0.7s cubic-bezier(0.34, 1.45, 0.64, 1),
        background 0.55s ease,
        box-shadow 0.55s ease;
    }
.biome-celestial::before {
      content: '';
      position: absolute;
      width: 8px;
      height: 8px;
      border-radius: 50%;
      background: rgba(148, 163, 184, 0.45);
      top: 9px;
      left: 11px;
      transition: opacity 0.35s ease;
    }
.biome-sun-rays {
      position: absolute;
      inset: -6px;
      border-radius: 50%;
      border: 2px dashed rgba(253, 224, 71, 0.85);
      opacity: 0;
      transform: scale(0.5) rotate(0deg);
      transition: opacity 0.45s ease, transform 0.6s ease;
    }
.biome-cloud {
      position: absolute;
      top: 12px;
      left: 16px;
      width: 30px;
      height: 11px;
      background: rgba(255, 255, 255, 0.92);
      border-radius: 99px;
      opacity: 0;
      transform: translateX(-24px);
      transition: opacity 0.5s ease 0.15s, transform 0.65s cubic-bezier(0.22, 1, 0.36, 1) 0.1s;
      z-index: 2;
    }
.biome-cloud::before {
      content: '';
      position: absolute;
      width: 14px;
      height: 14px;
      background: rgba(255, 255, 255, 0.95);
      border-radius: 50%;
      top: -6px;
      left: 5px;
    }
.biome-birds {
      position: absolute;
      top: 14px;
      left: 52px;
      opacity: 0;
      transform: translateY(10px) scale(0.7);
      transition: opacity 0.45s ease 0.2s, transform 0.6s ease 0.2s;
      z-index: 2;
    }
$on {
      background: linear-gradient(180deg, #0284c7 0%, #38bdf8 58%, #bae6fd 100%);
      box-shadow:
        inset 0 2px 8px rgba(255, 255, 255, 0.35),
        0 0 22px rgba(56, 189, 248, 0.35);
    }
$on .biome-stars span {
      opacity: 0;
      transform: translateY(-14px);
    }
$on .biome-celestial {
      transform: translateX(70px);
      background: radial-gradient(circle at 35% 35%, #fef08a 0%, #facc15 65%, #f59e0b 100%);
      box-shadow: 0 0 20px #fde047, 0 0 36px rgba(250, 204, 21, 0.7);
    }
$on .biome-celestial::before {
      opacity: 0;
    }
$on .biome-sun-rays {
      opacity: 1;
      animation: KF_sunCorona 9s linear infinite;
    }
@keyframes KF_sunCorona {
      from { transform: scale(1) rotate(0deg); }
      to { transform: scale(1) rotate(360deg); }
    }
$on .biome-hills {
      background: #15803d;
    }
$on .biome-hills::after {
      background: #16a34a;
    }
$on .biome-cloud {
      opacity: 1;
      transform: translateX(0);
    }
$on .biome-birds {
      opacity: 1;
      transform: translateY(0) scale(1);
    }

$ {
      position: relative;
      width: 126px;
      height: 58px;
      border-radius: 10px;
      background: #111318;
      padding: 4px;
      border: 1.5px solid #27272a;
      box-shadow:
        0 10px 22px rgba(0, 0, 0, 0.85),
        inset 0 2px 4px rgba(0, 0, 0, 0.95);
      perspective: 500px;
    }
.breaker-hazard {
      position: absolute;
      inset: 3px;
      border-radius: 7px;
      background: repeating-linear-gradient(
        -45deg,
        #eab308,
        #eab308 6px,
        #18181b 6px,
        #18181b 12px
      );
      opacity: 0.85;
    }
.breaker-well {
      position: relative;
      width: 100%;
      height: 100%;
      border-radius: 5px;
      background: linear-gradient(180deg, #090a0d 0%, #18181b 100%);
      box-shadow: inset 0 4px 10px rgba(0, 0, 0, 0.95);
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 0 12px;
      overflow: hidden;
    }
.breaker-status-lamp {
      width: 8px;
      height: 22px;
      border-radius: 2px;
      background: #3f3f46;
      box-shadow: inset 0 1px 2px rgba(0, 0, 0, 0.9);
      transition: background 0.2s ease, box-shadow 0.2s ease;
    }
.breaker-lever {
      position: absolute;
      top: 5px;
      left: 6px;
      width: 48px;
      height: 36px;
      border-radius: 5px;
      background: linear-gradient(180deg, #71717a 0%, #3f3f46 48%, #27272a 100%);
      border: 1px solid #a1a1aa;
      box-shadow:
        4px 4px 10px rgba(0, 0, 0, 0.8),
        inset 0 1px 1px rgba(255, 255, 255, 0.4);
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 4px;
      transform-origin: center;
      transition: transform 0.24s cubic-bezier(0.18, 0.89, 0.32, 1.28), background 0.25s ease, border-color 0.25s ease;
      z-index: 3;
    }
.breaker-lever span {
      width: 2.5px;
      height: 18px;
      background: rgba(0, 0, 0, 0.45);
      border-right: 1px solid rgba(255, 255, 255, 0.2);
      border-radius: 1px;
    }
.breaker-guard {
      position: absolute;
      inset: 2px;
      border-radius: 6px;
      background: linear-gradient(135deg, rgba(239, 68, 68, 0.24) 0%, rgba(239, 68, 68, 0.08) 100%);
      border: 1px solid rgba(248, 113, 113, 0.45);
      box-shadow: inset 0 1px 2px rgba(255, 255, 255, 0.25);
      transform-origin: top center;
      transform: rotateX(0deg);
      transition: transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1), opacity 0.25s ease;
      z-index: 4;
      pointer-events: none;
    }
$h:hover .breaker-guard {
      transform: rotateX(48deg);
    }
$on .breaker-guard {
      transform: rotateX(78deg);
      opacity: 0.45;
    }
$on .breaker-lever {
      transform: translateX(52px);
      background: linear-gradient(180deg, #f97316 0%, #c2410c 52%, #7c2d12 100%);
      border-color: #fdba74;
      box-shadow:
        -4px 4px 12px rgba(0, 0, 0, 0.85),
        0 0 16px rgba(249, 115, 22, 0.55);
    }
$on .breaker-status-lamp {
      background: #ef4444;
      box-shadow: 0 0 12px #ef4444, 0 0 24px rgba(239, 68, 68, 0.8);
    }

$ {
      position: relative;
      width: 126px;
      height: 56px;
      border-radius: 999px;
      background: #040508;
      border: 1px solid rgba(168, 85, 247, 0.25);
