.event-horizon-group {
      position: absolute;
      top: 6px;
      left: 6px;
      width: 42px;
      height: 42px;
      display: flex;
      align-items: center;
      justify-content: center;
      transition: transform 0.65s cubic-bezier(0.34, 1.4, 0.64, 1);
