      animation: KF_diskRotate 3.5s linear infinite;
      transition: opacity 0.4s ease, transform 0.5s ease;
    }
.relativistic-jet {
      position: absolute;
      width: 2px;
      height: 54px;
      background: linear-gradient(180deg, transparent 0%, #e879f9 50%, transparent 100%);
      box-shadow: 0 0 10px #d946ef;
      opacity: 0;
      transform: scaleY(0.2);
      transition: opacity 0.4s ease, transform 0.5s cubic-bezier(0.34, 1.56, 0.64, 1);
    }
.void-core {
      position: relative;
      width: 24px;
      height: 24px;
      border-radius: 50%;
      background: #000000;
      box-shadow:
        0 0 0 2px rgba(216, 180, 254, 0.65),
