$ {
      position: relative;
      width: 126px;
      height: 56px;
      border-radius: 999px;
      background: linear-gradient(180deg, #0e131f 0%, #1a2234 100%);
      box-shadow:
        inset 0 4px 10px rgba(0, 0, 0, 0.85),
        inset 0 -2px 4px rgba(255, 255, 255, 0.08),
        0 0 0 1px rgba(255, 255, 255, 0.1);
      overflow: hidden;
    }
.mercury-ripple {
      position: absolute;
      top: 50%;
      left: 28px;
      width: 20px;
      height: 20px;
      border-radius: 50%;
      border: 2px solid rgba(148, 163, 184, 0.5);
      transform: translate(-50%, -50%) scale(0.4);
      opacity: 0;
      pointer-events: none;
    }
$on .mercury-ripple {
      left: 98px;
      border-color: rgba(56, 189, 248, 0.75);
      animation: KF_mercuryRippleOut 0.7s cubic-bezier(0.16, 1, 0.3, 1) forwards;
    }
$off .mercury-ripple {
      left: 28px;
      animation: KF_mercuryRippleOut 0.7s cubic-bezier(0.16, 1, 0.3, 1) forwards;
    }
@keyframes KF_mercuryRippleOut {
      0% { transform: translate(-50%, -50%) scale(0.5); opacity: 0.9; }
      100% { transform: translate(-50%, -50%) scale(3.4); opacity: 0; }
    }
.mercury-drop {
      position: absolute;
      top: 6px;
      left: 6px;
      width: 44px;
      height: 44px;
      border-radius: 50%;
      background:
        radial-gradient(circle at 30% 25%, #ffffff 0%, #e2e8f0 22%, #64748b 58%, #1e293b 88%, #94a3b8 100%);
      box-shadow:
        0 6px 14px rgba(0, 0, 0, 0.75),
        inset 0 -4px 8px rgba(15, 23, 42, 0.85),
        inset 0 3px 6px rgba(255, 255, 255, 0.95);
      transition: transform 0.72s cubic-bezier(0.68, -0.55, 0.26, 1.55);
      transform-origin: center;
    }
.mercury-drop::after {
      content: '';
      position: absolute;
      top: 7px;
      left: 10px;
      width: 14px;
      height: 7px;
      border-radius: 50%;
      background: rgba(255, 255, 255, 0.92);
      transform: rotate(-25deg);
    }
$on .mercury-drop {
      transform: translateX(70px);
      background:
        radial-gradient(circle at 30% 25%, #ffffff 0%, #bae6fd 24%, #0284c7 60%, #082f49 88%, #38bdf8 100%);
      animation: KF_mercuryWobbleRight 0.75s ease;
    }
$off .mercury-drop {
      animation: KF_mercuryWobbleLeft 0.75s ease;
    }
@keyframes KF_mercuryWobbleRight {
      0% { transform: translateX(0) scale(1, 1); }
      25% { transform: translateX(34px) scale(1.42, 0.68); }
      50% { transform: translateX(78px) scale(0.76, 1.26); }
      72% { transform: translateX(66px) scale(1.14, 0.88); }
      88% { transform: translateX(71px) scale(0.95, 1.05); }
      100% { transform: translateX(70px) scale(1, 1); }
